// app/envios/acciones.ts
"use server";
import { revalidatePath } from "next/cache";
import { agregarEnvio } from "@/lib/envios";

export async function crearEnvio(formData: FormData) {
  const cliente = String(formData.get("cliente") ?? "").trim();
  const bultos = Number(formData.get("bultos") ?? 1);
  if (!cliente || !Number.isInteger(bultos) || bultos < 1) return;
  await agregarEnvio(cliente, bultos);
  revalidatePath("/envios");   // pide que la lista se calcule de nuevo
}

